/**
 * Themenbloecke aus den amtlichen Lehrplaenen – ERZEUGT, nicht von Hand gepflegt.
 *
 * Quelle der Erzeugung: recherche/themen/themen_ts.py aus den dort abgelegten
 * Lehrplandateien. Wer einen Lehrplan nachtraegt, aendert das Skript und laesst es neu
 * laufen; von Hand hier zu schreiben faellt beim naechsten Lauf wieder heraus.
 *
 * Was hier bewusst FEHLT:
 * - Deutsch Bayern: Der Fachlehrplan hat in allen Jahrgangsstufen 5–10 dasselbe
 *   Inhaltsverzeichnis (Sprechen und Zuhoeren / Lesen / Schreiben / Sprachgebrauch). Es gibt
 *   dort keine jahrgangsbezogenen Themenueberschriften – die Inhalte stecken nur in den
 *   Kompetenzformulierungen. Eine daraus gebastelte Liste waere erfunden.
 * - Englisch Nordrhein-Westfalen: Der Kernlehrplan kennt keine Inhaltsfelder.
 * - Ueberschriften, die keinen Unterrichtsgegenstand benennen („Erkenntnisse gewinnen –
 *   kommunizieren – bewerten", „Profilbereich am NTG").
 *
 * Die drei Laender ordnen ihre Themen unterschiedlich verbindlich zu – siehe `zuordnung`
 * in themen.ts. Bayern ist jahrgangsscharf, Berlin/Brandenburg fuehrt Doppeljahrgaenge,
 * Nordrhein-Westfalen nur zwei Baender (5/6 und 7–10) ohne Jahrgangszuordnung.
 */
